splay":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Hedge Fund","specialization":"Systematic Investing","seniority":"Analyst","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":null,"application_deadline":null,"salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"https://careers.point72.com/CSJobDetail?jobName=entry-level-quantitative-researcher&jobCode=CSS-0012600","source_url":"https://careers.point72.com/CSJobDetail?jobName=entry-level-quantitative-researcher&jobCode=CSS-0012600","source_name":"Point72 public careers site","status":"active","summary":"Entry-level quantitative research role with Cubist Systematic Strategies. The position focuses on predictive modelling, alpha-signal research, backtesting and portfolio analysis, with Toronto listed among the available locations.","description_text":"Cubist Systematic Strategies, an affiliate of Point72, is hiring an Entry-Level Quantitative Researcher. The role conducts original quantitative alpha-signal research and manages the research process from idea generation and data analysis through hypothesis testing, strategy generation, backtesting and portfolio analysis. Applicants should have a quantitative degree, Python or comparable programming experience, working SQL knowledge and strong analytical skills. Prior financial-services experience is not required.","description_status":"verified","description_verified_at":"2026-09-29T02:31:18.723Z","source_record_id":"point72:CSS-0012600","data_quality_notes":"Curated from the supplied workbook and linked to Point72's public careers page. The employer lists Toronto among several eligible global locations.","last_verified_at":"2026-09-29T02:31:18.723Z","updated_at":"2026-09-29T02:31:18.723Z"},{"external_job_id":"4466574529","company_id":"peakhill-capital","company_name":"Peakhill Capital","title":"Associate, Credit Investments","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Private Credit","specialization":"Commercial Real Estate Debt","seniority":"Associate","employment_type":null,"program_type":null,"term_start":null,"term_end":null,"term_length_months":null,"date_posted":null,"application_deadline":null,"salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"https://www.linkedin.com/jobs/search-results/?currentJobId=4466574529&trk=d_flagship3_company&refId=0CuiyHCA2M7h1uUHAIlTlg%3D%3D&trackingId=83BtNibSZz0Wfkk3lLYoHw%3D%3D&keywords=jobs&origin=COMPANY_PAGE_JOBS_CLUSTER_EXPANSION&originToLandingJobPostings=4466574529%2C4466586387&geoId=101174742&f_C=55051151%2C108894096","source_url":"https://www.linkedin.com/jobs/search-results/?currentJobId=4466574529","source_name":"User-supplied LinkedIn posting","status":"active","summary":"Toronto-based associate role on Peakhill Capital's debt platform, underwriting and funding commercial mortgage investments across Canadian real estate asset classes.","description_text":"Peakhill Capital is seeking an Associate, Credit Investments for its Toronto debt team. The role performs borrower and asset due diligence, financial analysis, commercial mortgage underwriting and funding, prepares credit and legal documentation, works with clients and the internal credit committee, and monitors commercial mortgage market conditions. The posting requests one to two years of commercial lending or real estate experience and familiarity with CMHC programs.","description_status":"verified","description_verified_at":"2026-09-29T02:31:18.723Z","source_record_id":"linkedin:4466574529","data_quality_notes":"Added from a user-supplied posting. LinkedIn job ID 4466574529 is used as the stable external identifier; no employer-hosted application URL was supplied.","last_verified_at":"2026-09-29T02:31:18.723Z","updated_at":"2026-09-29T02:31:18.723Z"},{"external_job_id":"anson-investment-analyst-2026-09","company_id":"anson-funds","company_name":"Anson Funds","title":"Investment Analyst","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":"On-site","category":"Hedge Fund","specialization":"Fundamental Public Markets","seniority":"Analyst","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":null,"application_deadline":null,"salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"/jobs/anson-funds-investment-analyst","source_url":"/job-postings/anson-funds-investment-analyst-2026-09.pdf","source_name":"Anson Funds employer PDF supplied to BSO","status":"active","summary":"Toronto-based fundamental public-markets analyst role supporting long and short idea generation, company research, financial modelling and portfolio analysis at Anson Funds.","description_text":"Anson Funds is seeking an Investment Analyst for its Toronto investment team. The role works with senior investors on fundamental public-company research, financial analysis, valuation, long and short investment theses, idea sourcing and ongoing portfolio analysis. It is an in-office position five days per week and requests two to five years of experience in investment banking, private equity, equity research, investment management or financial consulting. Applicants should send a resume and cover letter to Sunny Puri, Co-Head, Investments, at spuri@ansonfunds.com.","description_status":"verified","description_verified_at":"2026-09-29T02:31:18.723Z","source_record_id":"bso-exclusive:anson-investment-analyst-2026-09","data_quality_notes":"BSO Exclusive. Employer-supplied PDF reviewed in full. Applications are by email to Sunny Puri with a resume and cover letter.","last_verified_at":"2026-09-29T02:31:18.723Z","updated_at":"2026-09-29T02:31:18.723Z"},{"external_job_id":"6742077","company_id":"birch-hill-equity-partners","company_name":"Birch Hill Equity Partners","title":"Associate","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":null,"category":"Private Equity","specialization":"Middle-Market Private Equity","seniority":"Associate","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":null,"application_deadline":null,"salary_min":null,"salary_max":null,"salary_currency":null,"salary_period":null,"application_url":"https://job-boards.greenhouse.io/birchhillequity/jobs/6742077","source_url":"https://job-boards.greenhouse.io/birchhillequity/jobs/6742077","source_name":"Birch Hill Equity Partners Greenhouse","status":"active","summary":"Toronto-based private-equity Associate role covering deal sourcing, due diligence, business analysis, transaction execution and portfolio-company support.","description_text":"Birch Hill Equity Partners is hiring an Associate in Toronto. The three-year associate program participates across the investment process, including deal sourcing, due diligence, business analysis, deal execution and ongoing portfolio-company support. The employer typically seeks candidates with two to four years of experience from a leading investment bank or consulting firm and requires a resume and cover letter through its Greenhouse application.","description_status":"verified","description_verified_at":"2026-09-29T02:31:18.723Z","source_record_id":"greenhouse:birchhillequity:6742077","data_quality_notes":"Employer-hosted Greenhouse application verified active on September 28, 2026. No application deadline is displayed.","last_verified_at":"2026-09-29T02:31:18.723Z","updated_at":"2026-09-29T02:31:18.723Z"},{"external_job_id":"investment-analyst-2026-08","company_id":"edgepoint-investment-group","company_name":"EdgePoint Investment Group","title":"Investment Analyst","location_display":"Toronto, ON","city":"Toronto","province":"ON","country":"Canada","workplace_type":"On-site","category":"Asset Management","specialization":"Fundamental Public Equities","seniority":"Analyst","employment_type":"Full-time","program_type":"Full-time","term_start":null,"term_end":null,"term_length_months":null,"date_posted":"2026-08-07","application_deadline":"2026-09-30","salary_min":80000,"salary_max":120000,"salary_currency":"CAD","salary_period":"year","application_url":"mailto:WeAreGrowing@edgepointwealth.com?subject=Investment%20Analyst%20Application","source_url":"https://assets.ctfassets.net/kq9jrkvln56p/6tYhNgtrdrq3jICHoMzXfo/5a5d94984beea22b1d40f404164835b6/2026-08_investment_analyst.pdf","source_name":"EdgePoint employer job posting","status":"active","summary":"Toronto-based Investment Analyst role on EdgePoint's concentrated fundamental investment team, researching businesses and contributing directly to investment discussions.","description_text":"EdgePoint Investment Group is hiring an Investment Analyst for its Toronto investment team. The analyst researches and analyzes public companies, participates in management meetings, and regularly presents investment views to a 15-person investment team. Compensation includes a stated base salary range of CAD 80,000 to CAD 120,000, annual bonus and company equity participation. Applicants must submit a resume, cover letter and the two written investment prompts specified in the employer posting to WeAreGrowing@edgepointwealth.com by September 30, 2026.","description_status":"verified","description_verified_at":"2026-09-29T02:31:18.723Z","source_record_id":"edgepoint:investment-analyst-2026-08","data_quality_notes":"Employer PDF and August 7, 2026 EdgePoint hiring notice reviewed. The application deadline and compensation range come directly from the employer PDF.","last_verified_at":"2026-09-29T02:31:18.723Z","updated_at":"2026-09-29T02:31:18.723Z"}]$jobs$::jsonb)
  AS job(
    external_job_id text, company_id text, company_name text, title text, location_display text, city text, province text,
    country text, workplace_type text, category text, specialization text, seniority text, employment_type text,
    program_type text, term_start text, term_end text, term_length_months integer, date_posted text,
    application_deadline text, salary_min numeric, salary_max numeric, salary_currency text, salary_period text,
    application_url text, source_url text, source_name text, status text, summary text, description_text text,
    description_status text, description_verified_at text, source_record_id text, data_quality_notes text,
    last_verified_at text, updated_at text
  )
)
INSERT INTO public.jobs (external_job_id, company_id, company_name, title, location_display, city, province, country, workplace_type, category, specialization, seniority, employment_type, program_type, term_start, term_end, term_length_months, date_posted, application_deadline, salary_min, salary_max, salary_currency, salary_period, application_url, source_url, source_name, status, summary, description_text, description_status, description_verified_at, source_record_id, data_quality_notes, last_verified_at, updated_at)
SELECT
  job.external_job_id,
  COALESCE((SELECT company_id FROM public.companies WHERE name = job.company_name), job.company_id),
  job.company_name, job.title, job.location_display, job.city, job.province, job.country, job.workplace_type,
  job.category, job.specialization, job.seniority, job.employment_type, job.program_type,
  NULLIF(job.term_start, '')::date, NULLIF(job.term_end, '')::date, job.term_length_months,
  NULLIF(job.date_posted, '')::date, NULLIF(job.application_deadline, '')::date,
  job.salary_min, job.salary_max, job.salary_currency, job.salary_period,
  job.application_url, job.source_url, job.source_name, job.status, job.summary, job.description_text,
  job.description_status, NULLIF(job.description_verified_at, '')::timestamptz, job.source_record_id,
  job.data_quality_notes, NULLIF(job.last_verified_at, '')::timestamptz, now()
FROM incoming AS job
ON CONFLICT (source_record_id) DO UPDATE SET
  company_name = EXCLUDED.company_name,
  title = EXCLUDED.title,
  location_display = EXCLUDED.location_display,
  city = EXCLUDED.city,
  province = EXCLUDED.province,
